$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$a=(string)($_POST['action']??'');
 try{
  if($a==='variant_save'){$id=(int)($_POST['id']??0);$car=(int)($_POST['car_id']??0);$name=trim((string)($_POST['name']??''));$trans=trim((string)($_POST['transmission']??''));$price=trim((string)($_POST['price']??''));$desc=trim((string)($_POST['description']??''));$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['is_active'])?1:0;if(!$car||$name==='')throw new RuntimeException('Pilih kendaraan dan isi nama tipe.');if($price!==''&&!is_numeric($price))throw new RuntimeException('Harga harus berupa angka.');$pv=$price===''?null:(float)$price;if($id){$q=db()->prepare('UPDATE car_variants SET car_id=?,name=?,transmission=?,price=?,description=?,sort_order=?,is_active=? WHERE id=?');$q->execute([$car,$name,$trans?:null,$pv,$desc?:null,$sort,$active,$id]);}else{$q=db()->prepare('INSERT INTO car_variants(car_id,name,transmission,price,description,sort_order,is_active) VALUES(?,?,?,?,?,?,?)');$q->execute([$car,$name,$trans?:null,$pv,$desc?:null,$sort,$active]);}$success='Tipe kendaraan tersimpan.';}
  elseif($a==='variant_delete'){$q=db()->prepare('DELETE FROM car_variants WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Tipe kendaraan dihapus beserta data terkait jika foreign key disetel CASCADE.';}
