  elseif($a==='spec_delete'){$q=db()->prepare('DELETE FROM car_specifications WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Spesifikasi dihapus.';}
  elseif($a==='color_save'){$vid=(int)$_POST['variant_id'];$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$code=trim((string)($_POST['color_code']??''));$image=trim((string)$_POST['image_url']);$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['is_active'])?1:0;if(!$vid||$name===''||!filter_var($image,FILTER_VALIDATE_URL))throw new RuntimeException('Nama warna dan URL gambar yang valid wajib diisi.');if($code!==''&&!preg_match('/^#?[0-9a-fA-F]{3,8}$/',$code))throw new RuntimeException('Kode warna harus format HEX, contoh #ffffff.');if($code!==''&&$code[0]!=='#')$code='#'.$code;if($id){$q=db()->prepare('UPDATE car_colors SET name=?,color_code=?,image_url=?,sort_order=?,is_active=? WHERE id=? AND variant_id=?');$q->execute([$name,$code?:null,$image,$sort,$active,$id,$vid]);}else{$q=db()->prepare('INSERT INTO car_colors(variant_id,name,color_code,image_url,sort_order,is_active) VALUES(?,?,?,?,?,?)');$q->execute([$vid,$name,$code?:null,$image,$sort,$active]);}$success='Warna tersimpan.';}
  elseif($a==='color_delete'){$q=db()->prepare('DELETE FROM car_colors WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Warna dihapus.';}
 }catch(Throwable $e){$error=$e->getMessage();}
}
$cars=db()->query('SELECT id,name FROM cars ORDER BY sort_order,name')->fetchAll();$variants=db()->query('SELECT v.*,c.name car_name FROM car_variants v JOIN cars c ON c.id=v.car_id ORDER BY c.sort_order,c.name,v.sort_order,v.name')->fetchAll();$edit=null;$editId=(int)($_GET['edit']??0);if($editId){$q=db()->prepare('SELECT * FROM car_variants WHERE id=?');$q->execute([$editId]);$edit=$q->fetch()?:null;}$selected=(int)($_GET['variant']??0);if(!$selected&&$variants)$selected=(int)$variants[0]['id'];$activeVariant=null;foreach($variants as $v)if((int)$v['id']===$selected)$activeVariant=$v;$specs=[];$colors=[];if($activeVariant){$q=db()->prepare('SELECT * FROM car_specifications WHERE variant_id=? ORDER BY spec_group,sort_order,id');$q->execute([$selected]);$specs=$q->fetchAll();$q=db()->prepare('SELECT * FROM car_colors WHERE variant_id=? ORDER BY sort_order,id');$q->execute([$selected]);$colors=$q->fetchAll();}
